), faixas AS (
 SELECT f.*,
 CASE WHEN categoria ~ '^[MF][0-9]{4}$' THEN substring(categoria,2,2)::int WHEN categoria='M70+' THEN 70 ELSE 18 END AS idade_min,
 CASE WHEN categoria ~ '^[MF][0-9]{4}$' THEN substring(categoria,4,2)::int+1 ELSE 120 END AS idade_max,
 CASE WHEN categoria ~ '^[MF][0-9]{4}$' THEN 'faixa' WHEN categoria='M70+' THEN '70+' ELSE 'sem idade' END AS tipo
 FROM fonte f
), indices AS (
 SELECT column1 AS lo,column2 AS hi,column3*60 AS m,column4*60 AS f
 FROM (VALUES (18,34,175,205),(35,39,180,210),(40,44,185,215),(45,49,195,225),
 (50,54,200,230),(55,59,210,240),(60,64,230,260),(65,69,245,275),(70,74,260,290),
 (75,79,275,305),(80,120,290,320)) v
), calculo AS (
 SELECT f.*,CASE WHEN sexo='M' THEN i.m ELSE i.f END AS limite_mais_exigente,
 CASE WHEN sexo='M' THEN j.m ELSE j.f END AS limite_mais_permissivo
 FROM faixas f JOIN indices i ON idade_min BETWEEN i.lo AND i.hi
 JOIN indices j ON idade_max BETWEEN j.lo AND j.hi
)
SELECT CASE WHEN modalidade=0 THEN '42K geral e elite' ELSE '42K PCD — separado' END AS recorte,
 sexo,count(*) AS classificados,
 count(*) FILTER (WHERE segundos<=limite_mais_exigente) AS minimo_pelo_indice_geral,
 count(*) FILTER (WHERE segundos<=limite_mais_permissivo) AS teto_teorico_nao_estimativa,
 count(*) FILTER (WHERE segundos>limite_mais_exigente AND segundos<=limite_mais_permissivo AND tipo='faixa') AS pendentes_faixa,
 count(*) FILTER (WHERE segundos>limite_mais_exigente AND segundos<=limite_mais_permissivo AND tipo='70+') AS pendentes_70mais,
 count(*) FILTER (WHERE segundos>limite_mais_exigente AND segundos<=limite_mais_permissivo AND tipo='sem idade') AS pendentes_sem_idade,
 CASE WHEN modalidade=0 THEN CASE WHEN sexo='M' THEN 686 ELSE 222 END END AS publicado_no_post
FROM calculo GROUP BY modalidade,sexo ORDER BY modalidade,sexo
